import {skillFeedback,skillEffectMarkup,skillCutinMarkup,SKILL_CUTIN_MS,SKILL_STAGE_MS} from './skill-presentation.js';
import {EMOTES,EMOTE_DURATION,canSendEmote,privateDrawCue,emoteSprite,emoteLabel} from './emotes.js';
import {createGame,dispatch,nextActive,pairs,label,POINTS,SKILLS,skillUnavailable,botSkillAction,viewFor} from './game.js';
import {CHARACTERS,imagePath,cutinPath,readProfile,saveProfile} from './data.js';
const app=document.querySelector('#app');
let profile=readProfile(),screen='home',game=null,deadline=0,job=null,paused=false,pauseRemaining=0,modal=null,selectedCharacter=profile.character,emoteOpen=false,emoteUntil=0,lastEmote=null,emoteText='',dragged=null,scored=false;
let homeLine=0,modeOpen=false,drawerOpen=false,roomEmote=null,roomEmoteUntil=0,roomEmoteJob=null;
let audioCtx,sortMode=false,sortCard=null,skillTarget=1,skillRemaining=0,skillResumeActor=null,animationUntil=0;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const portrait=(c,cls='')=>`<div class="portrait ${cls}" style="--portrait:url('${imagePath(c)}');--ps:${c.portrait.size};--px:${c.portrait.x};--py:${c.portrait.y};--accent:${c.color}"></div>`;
const character=seat=>CHARACTERS[game.players[seat].character];
const seatName=seat=>seat===0?profile.nickname:character(seat).name;
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.id);toast.id=setTimeout(()=>el.classList.remove('show'),2800);}
function sound(kind='click'){
 if(!profile.sound)return;
 try{audioCtx??=new AudioContext();audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.connect(g);g.connect(audioCtx.destination);o.frequency.value=kind==='skill'?620:kind==='turn'?740:kind==='joker'?180:kind==='pair'?980:520;o.type='sine';g.gain.setValueAtTime(.065,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.17);o.start();o.stop(audioCtx.currentTime+.18);}catch{}
}
const brand=()=>`<a href="#" data-action="home" class="brand"><span class="brand-mark">♧</span><span>라스트 원<small>LAST ONE</small></span></a>`;
function header(gameMode=false){return `<header class="topbar">${brand()}<div class="header-center">${gameMode?`<span class="live-dot"></span> AI 연습 대전 <span class="muted">/</span> SET 01`:'친구 사이에도, 비밀은 있으니까.'}</div><div class="header-actions"><button class="icon-button" data-action="sound" aria-label="효과음 ${profile.sound?'끄기':'켜기'}">${profile.sound?'♪':'♩'}<span>${profile.sound?'소리 켜짐':'소리 꺼짐'}</span></button>${gameMode?'<button class="secondary small" data-action="menu">메뉴</button>':`<a class="text-link" href="/docs/" target="_blank" rel="noopener">기획서 ↗</a>`}</div></header>`;}
// Game-style main lobby: partner on stage, menu tiles on the side, no landing-page copy.
const MODES=[{id:'ai',name:'AI 대전',sub:'AI 3명과 한 세트',open:true},{id:'room',name:'친구 방',sub:'방 번호로 모이기'},{id:'short',name:'단기전',sub:'무작위 매칭 · 1세트'},{id:'three',name:'3세트전',sub:'무작위 매칭 · 합산'}];
function home(){const c=CHARACTERS[selectedCharacter],line=EMOTES[homeLine%EMOTES.length].id;return `<main class="main-lobby" style="--accent:${c.color}"><div class="lobby-bg" aria-hidden="true"><i class="lobby-glow"></i><i class="lobby-moon"></i></div><header class="lobby-top"><div class="lobby-profile">${portrait(c,'small')}<label><small>PLAYER</small><input id="nickname" maxlength="16" value="${esc(profile.nickname)}" autocomplete="off" aria-label="닉네임"></label><span class="lobby-stat"><small>플레이</small><b>${profile.sets}</b></span></div><div class="lobby-logo"><span>♧</span><b>라스트 원</b></div><button class="lobby-icon" data-action="sound" aria-label="효과음 ${profile.sound?'끄기':'켜기'}">${profile.sound?'♪':'♩'}</button></header><section class="lobby-stage" aria-label="파트너"><button class="lobby-poke" data-action="poke" aria-label="${c.name}에게 말 걸기"><img class="lobby-standing" src="${imagePath(c)}" alt="${c.name} 스탠딩"></button><div class="lobby-bubble" aria-live="polite">${homeLine?emoteSprite(c,line,'bubble-emote'):''}<span>${esc(emoteLabel(c,line))}</span></div><div class="lobby-nameplate"><small>PARTNER</small><strong>${c.name}</strong><span>${c.tag}</span></div></section><nav class="lobby-menu ${modeOpen?'open':''}" aria-label="대전"><button class="battle-button" data-action="battle" aria-expanded="${modeOpen}"><small>${modeOpen?'모드를 고르세요':'게임 시작'}</small><b>대전</b><i>${modeOpen?'×':'▶'}</i></button>${modeOpen?`<div class="mode-cards">${MODES.map((m,i)=>`<button class="mode-card ${m.open?'':'locked'}" data-action="${m.open?'lobby':'locked'}" style="--i:${i}"${m.open?'':' aria-disabled="true"'}><b>${m.name}</b><small>${m.open?m.sub:'준비 중'}</small></button>`).join('')}</div>`:''}</nav><footer class="lobby-dock"><button class="dock-tile" data-action="characters"><b>캐릭터</b><small>파트너 · 스킬</small></button><button class="dock-tile" data-action="emote-gallery"><b>이모티콘</b><small>16종</small></button><button class="dock-tile" data-action="help"><b>게임 방법</b><small>규칙 · 스킬</small></button><button class="dock-tile locked" data-action="locked" aria-disabled="true"><b>상점 · 친구 · 전적</b><small>준비 중</small></button></footer></main>`;}
function lobby(){const seats=[selectedCharacter,...[0,1,2,3].filter(i=>i!==selectedCharacter)],me=CHARACTERS[selectedCharacter],showEmote=roomEmote&&Date.now()<roomEmoteUntil;return `<main class="room" style="--accent:${me.color}"><div class="lobby-bg" aria-hidden="true"><i class="lobby-glow"></i></div><header class="room-top"><button class="room-back" data-action="home">← 로비</button><div class="room-rules"><b>AI 대전</b><span>1세트 · 턴 20초 · 스킬 세트당 1회</span></div><button class="lobby-icon" data-action="sound" aria-label="효과음 ${profile.sound?'끄기':'켜기'}">${profile.sound?'♪':'♩'}</button></header><section class="room-seats" aria-label="좌석">${seats.map((ci,i)=>{const c=CHARACTERS[ci],skill=SKILLS[ci],mine=i===0;return `<article class="seat ${mine?'is-me':''}" style="--accent:${c.color};--i:${i}"><span class="seat-badge">${mine?'나 · 방장':'AI'}</span>${mine&&showEmote?`<div class="seat-bubble">${emoteSprite(c,roomEmote,'bubble-emote')}<span>${esc(emoteLabel(c,roomEmote))}</span></div>`:''}<img class="seat-standing" src="${imagePath(c)}" alt="${c.name}">${mine?'<button class="seat-change" data-action="drawer">캐릭터 변경</button>':''}<div class="seat-plate"><b>${mine?esc(profile.nickname):c.name}</b><small>${mine?c.name+' · ':''}${c.tag}</small><span class="seat-skill" title="${esc(skill.description)}">✦ ${skill.name}</span></div></article>`;}).join('')}</section><footer class="room-bottom"><div class="room-emotes" aria-label="이모티콘">${EMOTES.map(e=>`<button data-action="room-emote" data-value="${e.id}" aria-label="${e.description}">${emoteSprite(me,e.id)}</button>`).join('')}</div><button class="room-start" data-action="start"><b>게임 시작</b><small>AI 3명 준비 완료</small></button></footer>${drawerOpen?`<div class="drawer-backdrop" data-action="drawer"></div><section class="room-drawer" role="dialog" aria-label="캐릭터 변경"><header><b>캐릭터 변경</b><button class="modal-close" data-action="drawer" aria-label="닫기">×</button></header><div class="drawer-list">${CHARACTERS.map((c,i)=>`<button class="drawer-choice ${i===selectedCharacter?'selected':''}" data-action="pick" data-index="${i}" style="--accent:${c.color}">${portrait(c)}<span><b>${c.name}</b><small>${SKILLS[i].name}</small><em>${SKILLS[i].description}</em></span></button>`).join('')}</div></section>`:''}</main>`;}
function backCards(count,vertical=false){const step=count<=1?0:Math.min(vertical?36:34,(vertical?190:310)/(count-1));return `<div class="backs ${vertical?'vertical':''}" style="--count:${count};--step:${step}px;${vertical?`height:${64+step*(count-1)}px`:`width:${48+step*(count-1)}px`}" aria-label="뒷면 카드 ${count}장">${Array.from({length:count},(_,i)=>`<span class="card-back" style="--i:${i}"><i>♧</i></span>`).join('')}</div>`;}
function cardHtml(c,{draw=false,index=0,selected=false,pair=false,draggable=false}={}){
 if(draw)return `<button class="draw-card card-back ${selected?'selected':''}" data-action="select" data-index="${index}" aria-label="${index+1}번째 카드 ${selected?'다시 눌러 뽑기':'선택'}"><i>♧</i><small>${index+1}</small></button>`;
 return `<button class="playing-card ${['♥','♦'].includes(c.suit)?'red':''} ${c.rank===0?'joker':''} ${pair?'pair':''} ${sortMode&&sortCard===c.id?'sort-selected':''}" data-action="${pair?'discard':'card'}" data-card="${c.id}" ${draggable?'draggable="true"':''} aria-label="${label(c)} ${c.rank===0?'':c.suit}${pair?' 페어 버리기':''}"><span class="card-corner">${label(c)}<small>${c.suit}</small></span><strong>${c.rank===0?'♧':c.suit}</strong><span class="card-bottom">${label(c)}</span></button>`;
}
function player(seat,position){const c=character(seat),finished=game.order.includes(seat),status=finished?`${game.order.indexOf(seat)+1}번째 종료`:game.actor===seat?'행동 중':'';return `<div class="seat seat-${position} ${game.actor===seat&&!finished?'active':''}" data-seat="${seat}"><div class="seat-person">${portrait(c)}<b>${esc(seatName(seat))}</b><small>${status||'&nbsp;'}${game.shields?.[seat]?' · 반사 보호':game.skillUsed?.[seat]?' · 스킬 사용 완료':' · 스킬 1회'}</small></div>${!finished?backCards(game.players[seat].hand.length,position!=='top'):'<span class="finished-mark">✓</span>'}</div>`;}
function drawStage(){
 const source=nextActive(game,game.actor),mine=game.actor===0,hand=game.players[source].hand;
 return `<div class="draw-stage"><div class="draw-heading"><span class="eyebrow">${mine?'YOUR CHOICE':'THEIR CHOICE'}</span><h2>${mine?`${esc(seatName(source))}의 패에서 한 장을 고르세요`:`${esc(seatName(game.actor))}가 내 카드를 고르는 중`}</h2><p>${mine?'한 번 눌러 선택하고, 같은 카드를 다시 눌러 가져오세요.':'상대의 선택을 지켜보세요. 지금은 손패 순서를 바꿀 수 없습니다.'}</p></div><div class="draw-row" style="--n:${hand.length}">${hand.map((c,i)=>mine?cardHtml(c,{draw:true,index:i,selected:game.selected===i}):`<div class="defender-card ${game.selected===i?'selected':''}">${cardHtml(c)}</div>`).join('')}</div><div class="selection-hint">${game.selected==null?'어느 카드가 좋을까…':mine?`${game.selected+1}번째 카드 · 다시 누르면 뽑습니다`:`${game.selected+1}번째 카드를 고르고 있어요`}</div><div class="draw-people"><div>${portrait(character(source))}<b>${esc(seatName(source))}</b><small>카드를 주는 사람</small></div><span class="draw-arrow">→</span><div>${portrait(character(game.actor))}<b>${esc(seatName(game.actor))}</b><small>카드를 뽑는 사람</small></div></div></div>`;
}
function revealStage(){const d=game.draw,joker=d.card.rank===0;return `<div class="reveal-stage ${joker?'joker-reveal':''}"><div class="eyebrow">ONLY BETWEEN US</div><h2>${joker?'앗, 조커다!':'한 장, 가져왔습니다.'}</h2><div class="reveal-content"><div class="reaction giver">${joker?emoteSprite(character(d.source),'laugh','reaction-sticker'):`<img src="${imagePath(character(d.source))}" alt="${esc(seatName(d.source))}">`}<div><strong>${esc(seatName(d.source))}</strong><span>${joker?'휴… 이제 네 차례야.':'어떤 카드였을까?'}</span></div></div><div class="revealed-card">${cardHtml(d.card)}</div><div class="reaction taker">${joker?emoteSprite(character(d.actor),'shock','reaction-sticker'):`<img src="${imagePath(character(d.actor))}" alt="${esc(seatName(d.actor))}">`}<div><strong>${esc(seatName(d.actor))}</strong><span>${joker?'잠깐, 이건…!':'좋아, 다음은…'}</span></div></div></div><p class="reveal-note">잠시 후 테이블로 돌아갑니다 <span class="dots">···</span></p></div>`;}
function skillStage(){
 const event=viewFor(game,0).skill,skill=SKILLS[event.kind],feedback=skillFeedback(event);
 const elapsed=Math.max(0,Math.min(SKILL_STAGE_MS,SKILL_STAGE_MS-(paused?pauseRemaining:animationUntil-Date.now())));
 return `<div class="skill-stage skill-${feedback.type}" role="status" style="--cutin-delay:-${elapsed}ms;--effect-delay:${SKILL_CUTIN_MS-elapsed}ms;--effect-state:${paused?'paused':'running'};--accent:${character(event.actor).color}">${skillCutinMarkup(character(event.actor),{name:esc(seatName(event.actor)),skillName:skill.name,cutin:cutinPath(character(event.actor)),standing:imagePath(character(event.actor))})}<span class="eyebrow">${event.reflected?'SKILL REFLECTED':'ONCE PER SET'}</span><div class="skill-portrait">${skillEffectMarkup(event)}<img src="${imagePath(character(event.actor))}" alt="${esc(seatName(event.actor))}"></div><h2>${skill.name}</h2><p class="skill-quote">“${feedback.quote}”</p><p>${esc(seatName(event.actor))}${event.target===null?'의 스킬':` → ${esc(seatName(event.target))}`}</p><p class="skill-result">${feedback.result}</p>${event.card?`<div class="skill-private"><small>${feedback.privateLabel}</small><strong>${event.card.suit} ${label(event.card)}</strong></div>`:''}<small>연출 중에는 행동 시간이 흐르지 않아요.</small></div>`;
}
function skillDialog(){
 const kind=game.players[0].character,skill=SKILLS[kind],targets=game.players.filter(p=>p.id!==0&&p.hand.length);
 if(!targets.some(p=>p.id===skillTarget))skillTarget=targets[0]?.id;
 const cards=kind===0?game.players[0].hand.filter(c=>c.rank!==0):game.players[skillTarget]?.hand??[];
 return `<div class="modal-backdrop"><section class="modal skill-dialog" role="dialog" aria-modal="true" aria-labelledby="skill-title"><button class="modal-close" data-action="close" aria-label="닫기">×</button><span class="eyebrow">세트당 1회 · 선택 중에도 제한시간은 흐릅니다</span><h2 id="skill-title">${skill.name}</h2><p>${skill.description}</p>${kind<2?`<fieldset><legend>대상</legend><div class="skill-targets">${targets.map(p=>`<button data-action="skill-target" data-seat="${p.id}" class="secondary ${p.id===skillTarget?'chosen':''}" aria-pressed="${p.id===skillTarget}">${esc(seatName(p.id))} · ${p.hand.length}장${game.shields?.[p.id]?' · 반사 보호':''}</button>`).join('')}</div></fieldset><label>${kind===0?'넘길 내 카드':'확인할 상대 뒷면 카드'}<select id="skill-card">${cards.map((c,i)=>`<option value="${kind===0?c.id:i}">${kind===0?`${c.suit} ${label(c)}`:`뒷면 ${i+1}번`}</option>`).join('')}</select></label>`:''}${kind<2&&game.shields?.[skillTarget]?'<p class="skill-reflect-warning">이 대상은 반사 보호 중입니다. 반사돼도 사용 횟수는 소모됩니다.</p>':''}<button class="primary full" data-action="skill-confirm">스킬 사용 · 남은 1회</button><button class="text-button full" data-action="close">취소</button></section></div>`;
}
function table(){
 const humanDone=game.order.includes(0),myTurn=game.actor===0,source=nextActive(game,game.actor);
 const involved=[game.actor,source].includes(0),revealInvolved=game.draw&&[game.draw.actor,game.draw.source].includes(0);
 const special=game.phase==='skill'||(game.phase==='select'&&involved)||(game.phase==='reveal'&&revealInvolved);
 const ps=pairs(game.players[0].hand).flat(),canDiscard=game.phase==='discard'&&myTurn;
 const sortedAllowed=!humanDone&&!special&&!canDiscard;if(!sortedAllowed){sortMode=false;sortCard=null;}
 let status=game.phase==='skill'?'스킬 발동 중 · 타이머 정지':humanDone?'승리 확정 · 나머지 플레이를 기다립니다':myTurn?(game.phase==='action'?'내 차례입니다':canDiscard?'페어를 눌러 버리세요':'카드를 고르는 중'): `${esc(seatName(game.actor))}의 차례`;
 const elapsed=game.discarded.length,top=`<div class="game-status"><span class="eyebrow">TURN ${String(game.turn).padStart(2,'0')}</span><span>${status}</span><span class="timer ${deadline?'':'hidden'}"><i></i><b id="seconds">20</b>초</span></div>`;
 return `${header(true)}${top}<main class="game-shell"><div class="stage" id="stage">${special?(game.phase==='skill'?skillStage():game.phase==='reveal'?revealStage():drawStage()):`
 <div class="table-aura"></div><div class="discard-zone" data-testid="discard-zone"><span class="table-monogram">♧</span><h2>버리는 구역</h2><p>${elapsed?`${elapsed/2}개의 페어가 테이블을 떠났어요`:'같은 숫자의 카드 두 장을 버리세요'}</p><div class="discard-decoration"><span></span><i>LAST ONE</i><span></span></div></div>
 ${player(1,'right')}${player(2,'top')}${player(3,'left')}
 <div class="my-seat ${myTurn?'active':''}">${portrait(character(0))}<b>${esc(profile.nickname)}</b><small>${humanDone?'승리 확정':myTurn?'내 차례':'대기 중'}${game.shields?.[0]?' · 반사 보호':game.skillUsed?.[0]?' · 스킬 사용 완료':' · 스킬 1회'}</small>${emoteUntil>Date.now()?`<div class="emote-bubble" style="animation-delay:-${Math.max(0,Date.now()-lastEmote)}ms">${emoteSprite(character(0),emoteText)}<b>${emoteLabel(character(0),emoteText)}</b></div>`:''}</div>
 <div class="my-hand ${sortMode?'sorting':''}"><div class="hand-label">${humanDone?'잘했어요!':'내 손패'}<span>${humanDone?`이번 세트 +${POINTS[game.order.indexOf(0)].toLocaleString()}점`:canDiscard?'빛나는 카드를 눌러 페어 버리기':sortMode?'카드를 고르고 좌우 버튼으로 이동':'손패 순서를 바꿀 수 있어요'}</span>${sortedAllowed?`<button class="sort-toggle" data-action="sort-mode" aria-pressed="${sortMode}">${sortMode?'정렬 완료':'순서 변경'}</button>`:''}</div>${sortedAllowed&&sortMode?`<div class="sort-tools"><button data-action="sort-left" aria-label="선택 카드 왼쪽으로" ${!sortCard||game.players[0].hand[0]?.id===sortCard?'disabled':''}>◀</button><span>${sortCard?'선택한 카드를 옮기세요':'옮길 카드를 누르세요'}</span><button data-action="sort-right" aria-label="선택 카드 오른쪽으로" ${!sortCard||game.players[0].hand.at(-1)?.id===sortCard?'disabled':''}>▶</button></div>`:''}<div class="hand-cards" style="--hand-count:${game.players[0].hand.length}">${game.players[0].hand.map(c=>cardHtml(c,{pair:canDiscard&&ps.includes(c.id),draggable:sortedAllowed})).join('')}${humanDone?'<div class="spectator-note">잠시 다른 일을 해도 괜찮아요.<br>세트가 끝나면 알려드릴게요.</div>':''}</div></div>
 <div class="turn-action">${myTurn&&game.phase==='action'?`<button class="secondary skill-button" data-action="skill-open" ${skillUnavailable(game,0)?'disabled':''} title="${skillUnavailable(game,0)??SKILLS[game.players[0].character].description}">${SKILLS[game.players[0].character].name} · ${game.skillUsed?.[0]?0:1}회</button><button class="primary draw-button" data-action="begin">카드 뽑기 <span>→</span></button><small>${skillUnavailable(game,0)??'스킬 또는 카드 뽑기를 선택하세요'}</small>`:canDiscard?'<div class="pair-tip">짝을 찾았어요 <span>✦</span></div><small>20초 후 자동으로 버립니다</small>':`<div class="waiting-label"><span class="live-dot"></span>${humanDone?'테이블 관전 중':'상대가 생각하는 중'}</div>`}</div>`}
 ${!(game.phase==='reveal'&&revealInvolved)?`<div class="emote-control"><button class="emote-toggle" data-action="emotes" aria-label="이모티콘">☺</button>${emoteOpen?`<div class="emote-options"><small>모두에게 보내기</small>${EMOTES.map(e=>`<button data-action="emote" data-value="${e.id}" aria-label="${e.description} 보내기">${emoteSprite(character(0),e.id)}<span>${emoteLabel(character(0),e.id)}</span></button>`).join('')}</div>`:''}</div>`:''}
 ${special&&emoteUntil>Date.now()&&game.phase!=='reveal'?`<div class="emote-bubble draw-emote" style="animation-delay:-${Math.max(0,Date.now()-lastEmote)}ms">${emoteSprite(character(0),emoteText)}</div>`:''}</div></main><footer class="game-footer"><span>♧ 같은 숫자 두 장은 페어 · 마지막 조커 한 명만 패배</span><span>AI 대전 · 단일 세트 · 스킬 1회</span></footer>`;
}
function results(){return `${header()}<main class="result-page"><div class="eyebrow">SET COMPLETE</div><h1>${game.order[3]===0?'이번 조커는 내 곁에.':'조커는 두고, 승리만.'}</h1><p>다음 판에는 누가 마지막 카드를 갖게 될까요?</p><div class="result-list">${game.order.map((seat,i)=>`<div class="result-row ${seat===0?'is-me':''}"><span class="result-rank">0${i+1}</span>${emoteSprite(character(seat),i===3?'shock':'laugh','result-sticker')}<div class="result-player"><b>${esc(seatName(seat))}</b><span>${i===3?'조커 보유 · 패배':'승리 · '+(i+1)+'번째 종료'}</span></div><strong class="result-score">${POINTS[i]>0?'+':''}${POINTS[i].toLocaleString()}<small>세트 점수</small></strong></div>`).join('')}</div><div class="result-buttons"><button class="secondary large" data-action="home">로비로</button><button class="primary large" data-action="lobby">한 판 더 <span>↗</span></button></div><small class="result-disclaimer">여러 세트 합산 · 플레이 랭크 · 재화 보상은 후속 개발 예정입니다.</small></main>`;}
function overlay(){if(!modal)return '';if(modal==='skill')return skillDialog();if(modal==='characters')return `<div class="modal-backdrop"><section class="modal character-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close" data-action="close" aria-label="닫기">×</button><span class="eyebrow">CHARACTERS</span><h2 id="modal-title">캐릭터</h2><div class="character-modal-list">${CHARACTERS.map((c,i)=>`<article class="character-card ${i===selectedCharacter?'selected':''}" style="--accent:${c.color}"><img src="${imagePath(c)}" alt="${c.name}"><div><b>${c.name}</b><small>${c.tag}</small><p><strong>${SKILLS[i].name}</strong> ${SKILLS[i].description}</p><button class="${i===selectedCharacter?'secondary':'primary'} small" data-action="pick" data-index="${i}" ${i===selectedCharacter?'disabled':''}>${i===selectedCharacter?'현재 파트너':'파트너로 지정'}</button></div></article>`).join('')}</div></section></div>`;if(modal==='emote-gallery')return `<div class="modal-backdrop"><section class="modal emote-gallery" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close" data-action="close" aria-label="닫기">×</button><span class="eyebrow">CHARACTER EMOTES</span><h2 id="modal-title">작은 표정, 커다란 속마음.</h2><p>웃음 · 당황 · 인사 · 의심 — 캐릭터마다 네 가지 반응</p>${CHARACTERS.map(c=>`<div class="emote-gallery-row"><b>${c.name}</b>${EMOTES.map(e=>`<button data-action="preview-emote" aria-label="${c.name} ${e.description}">${emoteSprite(c,e.id)}<span>${emoteLabel(c,e.id)}</span></button>`).join('')}</div>`).join('')}</section></div>`;const help=modal==='help';return `<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close" data-action="close" aria-label="닫기">×</button><span class="eyebrow">${help?'HOW TO PLAY':'TAKE A BREATH'}</span><h2 id="modal-title">${help?'가볍게 배우는 도둑잡기':'잠깐 쉬어갈까요?'}</h2>${help?`<ol><li>52장의 카드와 조커 한 장을 나눠 갖습니다.</li><li>처음 가진 페어는 자동으로 버립니다.</li><li>오른쪽 플레이어의 카드 한 장을 뽑으세요.</li><li>같은 숫자 두 장이 모이면 눌러서 버립니다.</li><li>패를 모두 털면 승리, 마지막 조커는 패배!</li></ol><p>각 조작은 20초. 선택하면 다음 조작에 다시 20초가 주어집니다. 뽑기 결과는 두 당사자만 봅니다. 자기 차례의 뽑기 전에 캐릭터 스킬을 세트당 한 번 사용할 수 있습니다. 스킬 연출 동안은 타이머가 멈춥니다.</p><button class="primary" data-action="close">알겠어요</button>`:modal==='leave'?`<p>현재 세트는 저장되지 않습니다.<br>메인으로 돌아갈까요?</p><div class="modal-buttons"><button class="secondary" data-action="close">계속하기</button><button class="primary" data-action="leave">나가기</button></div>`:`<p>AI 대전과 타이머가 일시정지되었습니다.</p><button class="secondary full" data-action="sound">효과음 ${profile.sound?'켜짐 ♪':'꺼짐 ♩'}</button><button class="primary full" data-action="close">계속하기</button><button class="text-button full" data-action="confirm-leave">게임 나가기</button>`}</section></div>`;}
let renderedScreen=null;
function render(){
 const preserve=renderedScreen===screen;
 const position={x:scrollX,y:scrollY,scrollers:['.game-shell','.hand-cards','.draw-row'].map(selector=>({selector,left:document.querySelector(selector)?.scrollLeft??0}))};
 app.dataset.fresh=preserve?'0':'1';app.innerHTML=(screen==='home'?home():screen==='lobby'?lobby():screen==='result'?results():table())+overlay();
 fit();
 if(preserve){for(const {selector,left} of position.scrollers){const el=document.querySelector(selector);if(el)el.scrollLeft=left;}window.scrollTo({left:position.x,top:position.y,behavior:'instant'});}
 else window.scrollTo({left:0,top:0,behavior:'instant'});
 renderedScreen=screen;tick();
}
function fit(){const stage=document.querySelector('.stage');if(stage){if(innerWidth<=600){stage.style.setProperty('--scale',1);stage.parentElement.style.height='760px';return;}const scale=Math.min((innerWidth-32)/1440,(innerHeight-158)/810);stage.style.setProperty('--scale',Math.max(.35,scale));stage.parentElement.style.height=`${810*Math.max(.35,scale)}px`;}}
addEventListener('resize',fit);
function start(){clearTimeout(job);profile.nickname=(document.querySelector('#nickname')?.value.trim()||profile.nickname||'플레이어').slice(0,16);profile.character=selectedCharacter;saveProfile(profile);const others=[0,1,2,3].filter(i=>i!==selectedCharacter);const seed=Number(new URLSearchParams(location.search).get('seed'))||Date.now()%2147483647;game=createGame(seed,[selectedCharacter,...others]);screen='game';scored=false;sortMode=false;sortCard=null;paused=false;modal=null;emoteOpen=false;emoteUntil=0;lastEmote=null;sync();}
function act(action){try{const remaining=deadline?Math.max(1,deadline-Date.now()):20000,actor=game.actor;game=dispatch(game,action);if(action.type==='USE_SKILL'){skillRemaining=remaining;skillResumeActor=actor;sound('skill');}if(modal==='skill')modal=null;if(action.type==='DRAW'){const cue=privateDrawCue(game);if(cue)sound(cue.sound);}if(action.type==='DISCARD')sound('pair');sync(action.type);}catch(e){toast(e.message);}}
function sync(actionType){clearTimeout(job);deadline=0;animationUntil=0;if(game.phase==='ended'){screen='result';if(!scored){profile.sets++;saveProfile(profile);scored=true;sound('turn');}render();return;}
 const human=game.actor===0;
 if(game.phase==='reveal'||game.phase==='skill'){const ms=game.phase==='skill'?SKILL_STAGE_MS:3000;animationUntil=Date.now()+ms;job=setTimeout(()=>act({type:game.phase==='skill'?'END_SKILL':'END_REVEAL'}),ms);}
 else if(human){deadline=Date.now()+(actionType==='END_SKILL'&&game.actor===skillResumeActor?skillRemaining:20000);if(game.phase==='action')sound('turn');}
 else scheduleBot();render();
}
function scheduleBot(){const delay=game.phase==='action'?900:game.phase==='select'?(game.selected==null?950:1100):650;job=setTimeout(()=>{if(paused)return;if(game.phase==='action')act(botSkillAction(game)??{type:'BEGIN_DRAW'});else if(game.phase==='select'){const n=game.players[nextActive(game,game.actor)].hand.length;if(game.selected==null)act({type:'SELECT',index:Math.floor(Math.random()*n)});else act({type:'DRAW'});}else if(game.phase==='discard')act({type:'DISCARD'});},delay);}
function tick(){if(paused)return;const el=document.querySelector('#seconds');if(el)el.textContent=Math.max(0,Math.ceil((deadline-Date.now())/1000));if(screen==='game'&&deadline&&Date.now()>=deadline){deadline=0;toast('시간이 지나 자동으로 진행합니다.');if(game.phase==='action')act({type:'BEGIN_DRAW'});else if(game.phase==='select')act({type:'DRAW',index:game.selected??Math.floor(Math.random()*game.players[nextActive(game,game.actor)].hand.length)});else if(game.phase==='discard')act({type:'DISCARD'});}
 if(emoteUntil&&Date.now()>emoteUntil){emoteUntil=0;document.querySelector('.emote-bubble')?.remove();}}
setInterval(tick,100);
function openModal(name){modal=name;if(screen==='game'&&!paused){pauseRemaining=Math.max(1,(deadline||animationUntil||Date.now())-Date.now());clearTimeout(job);paused=true;}render();setTimeout(()=>document.querySelector('.modal button')?.focus({preventScroll:true}),0);}
function closeModal(){modal=null;if(paused){paused=false;if(game.phase==='reveal'||game.phase==='skill'){animationUntil=Date.now()+pauseRemaining;job=setTimeout(()=>act({type:game.phase==='skill'?'END_SKILL':'END_REVEAL'}),pauseRemaining);}else if(game.actor===0)deadline=Date.now()+pauseRemaining;else scheduleBot();}render();}
app.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();const a=b.dataset.action;if(a==='sound'){profile.sound=!profile.sound;saveProfile(profile);sound();render();return;}if(a==='close'){closeModal();return;}if(a==='help'){openModal('help');return;}if(a==='menu'){openModal('menu');return;}if(a==='confirm-leave'){openModal('leave');return;}if(a==='home'&&screen==='game'){openModal('leave');return;}if(a==='leave'||a==='home'){clearTimeout(job);deadline=0;paused=false;modal=null;modeOpen=false;drawerOpen=false;screen='home';render();return;}if(a==='lobby'){clearTimeout(job);deadline=0;screen='lobby';modeOpen=false;drawerOpen=false;sound();render();return;}if(a==='battle'){modeOpen=!modeOpen;sound();render();return;}if(a==='locked'){toast('준비 중인 기능이에요. 지금은 AI 대전만 열려 있어요.');return;}if(a==='poke'){homeLine++;sound();render();return;}if(a==='characters'){openModal('characters');return;}if(a==='drawer'){drawerOpen=!drawerOpen;render();if(drawerOpen)document.querySelector('.drawer-choice.selected')?.focus({preventScroll:true});return;}if(a==='room-emote'){roomEmote=b.dataset.value;roomEmoteUntil=Date.now()+EMOTE_DURATION;clearTimeout(roomEmoteJob);roomEmoteJob=setTimeout(()=>{if(screen==='lobby')render();},EMOTE_DURATION+20);sound();render();return;}if(a==='pick'||a==='pick-home'){const old=document.querySelector('#nickname')?.value;if(old)profile.nickname=old;selectedCharacter=Number(b.dataset.index);profile.character=selectedCharacter;saveProfile(profile);drawerOpen=false;homeLine=0;sound();render();return;}if(a==='start'){start();return;}if(a==='emotes'){emoteOpen=!emoteOpen;render();return;}if(a==='emote-gallery'){openModal('emote-gallery');return;}if(a==='preview-emote'){b.classList.remove('emote-preview-pop');void b.offsetWidth;b.classList.add('emote-preview-pop');sound();return;}if(a==='emote'){if(paused||screen!=='game')return;if(!canSendEmote(b.dataset.value,lastEmote,Date.now())){toast('조금만 기다렸다가 다시 보내세요.');return;}emoteText=b.dataset.value;lastEmote=Date.now();emoteUntil=lastEmote+EMOTE_DURATION;emoteOpen=false;sound();render();return;}if(paused||screen!=='game')return;if(a==='skill-open'){if(skillUnavailable(game,0)){toast(skillUnavailable(game,0));return;}skillTarget=nextActive(game,0);modal='skill';render();document.querySelector('.skill-dialog button')?.focus({preventScroll:true});return;}if(a==='skill-target'){skillTarget=Number(b.dataset.seat);render();document.querySelector(`[data-action=skill-target][data-seat="${skillTarget}"]`)?.focus({preventScroll:true});return;}if(a==='skill-confirm'){const kind=game.players[0].character,value=document.querySelector('#skill-card')?.value;act({type:'USE_SKILL',target:skillTarget,...(kind===0?{cardId:value}:kind===1?{index:Number(value)}:{})});return;}if(a==='sort-mode'){sortMode=!sortMode;sortCard=null;render();return;}if(a==='card'&&sortMode){sortCard=b.dataset.card;render();return;}if(a==='sort-left'||a==='sort-right'){const ids=game.players[0].hand.map(c=>c.id),i=ids.indexOf(sortCard),to=i+(a==='sort-left'?-1:1);if(i<0||to<0||to>=ids.length)return;ids.splice(to,0,ids.splice(i,1)[0]);try{game=dispatch(game,{type:'REORDER',seat:0,ids});render();}catch(err){sortMode=false;sortCard=null;toast(err.message);render();}return;}if(a==='begin')act({type:'BEGIN_DRAW'});if(a==='select'&&game.actor===0){const index=Number(b.dataset.index);act({type:game.selected===index?'DRAW':'SELECT',index});}if(a==='discard'&&game.actor===0)act({type:'DISCARD',cardId:b.dataset.card});});
document.addEventListener('change',e=>{if(e.target.id==='nickname'){profile.nickname=(e.target.value.trim()||'플레이어').slice(0,16);saveProfile(profile);}});
app.addEventListener('dragstart',e=>{const c=e.target.closest('[draggable=true]');if(c){dragged=c.dataset.card;e.dataTransfer.setData('text/plain',dragged);}});
app.addEventListener('dragover',e=>{if(e.target.closest('.my-hand .playing-card'))e.preventDefault();});
app.addEventListener('drop',e=>{const target=e.target.closest('.my-hand .playing-card');if(!target||!dragged)return;e.preventDefault();const ids=game.players[0].hand.map(c=>c.id),from=ids.indexOf(dragged),to=ids.indexOf(target.dataset.card);if(from<0||to<0)return;ids.splice(to,0,ids.splice(from,1)[0]);try{game=dispatch(game,{type:'REORDER',seat:0,ids});render();}catch(err){toast(err.message);}dragged=null;});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(drawerOpen){drawerOpen=false;render();return;}if(modeOpen&&screen==='home'){modeOpen=false;render();return;}if(modal)closeModal();else if(screen==='game')openModal('menu');}if(e.key==='Tab'&&modal){const items=[...document.querySelectorAll('.modal button:not(:disabled), .modal select, .modal input, .modal a[href]')],first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
if(new URLSearchParams(location.search).has('test'))window.__jokerTest={get state(){return game;},setState(s){clearTimeout(job);game=s;screen='game';paused=false;modal=null;sync();},act,timeout(){deadline=Date.now()-1;tick();},pause(){openModal('menu');},resume:closeModal};
render();

